"""Builds data/glossary.json: the glossary of terms and abbreviations used in the modules and the workbook.
abbr = exact strings that are underlined in the module text (case-sensitive, whole words). Edit here, rerun: python3 tools/make-glossary.py
Categories: basics, structure, docking, screening, adme, network, homology, md, stats, files, tools, site"""
import json
E = []
def G(id, term, abbr, full, d, cat, mods, more='', see=()):
    E.append(dict(id=id, term=term, abbr=list(abbr), full=full, def_=d, cat=cat, modules=list(mods), more=more, see=list(see)))
# ---------------------------------------------------------------- basics
G('cadd', 'CADD', ['CADD'], 'Computer-aided drug design', 'Using computers to help find and improve medicines: choosing targets, finding compounds, predicting how they bind and how they behave in the body.', 'basics', ['all'])
