G('lead', 'Lead', [], '', 'A confirmed, promising compound that is improved by chemistry to become a drug candidate.', 'screening', ['screening'])
G('candidate', 'Candidate', [], 'Drug candidate', 'A compound chosen to go forward to more detailed testing.', 'basics', ['all'])
G('scaffold', 'Scaffold', [], '', 'The core ring system or skeleton of a molecule. Compounds with the same scaffold are structurally similar.', 'screening', ['screening'])
G('analogue', 'Analogue', [], '', 'A compound that differs from another by a small change, for example a methyl group replaced by chlorine.', 'docking', ['docking', 'adme'])
G('fragment', 'Fragment', [], '', 'A very small molecule, often used as a starting point that chemists then grow.', 'docking', ['docking'])
G('pharmacophore', 'Pharmacophore', [], '', 'The set of features (for example hydrogen-bond donors, aromatic rings) in a given 3D arrangement that a molecule needs to bind a target.', 'screening', ['screening', 'network'])
G('sar', 'SAR', ['SAR'], 'Structure–activity relationship', 'How small changes in a molecule\'s structure change its activity.', 'screening', ['docking'])
G('ic50', 'IC50', ['IC50', 'IC₅₀'], 'Half-maximal inhibitory concentration', 'The concentration of a compound that reduces the activity of a target by half. Smaller means more potent.', 'basics', ['docking', 'project'])
G('kd', 'Kd', ['Kd'], 'Dissociation constant', 'A measure of binding strength: the concentration at which half of the target is bound. Smaller means tighter binding.', 'basics', ['docking'])
G('ki', 'Ki', ['Ki'], 'Inhibition constant', 'The binding constant of an inhibitor for an enzyme. Smaller means tighter binding.', 'basics', ['docking'])
G('mock', 'Mock / simulated data', [], '', 'Data made up or generated for teaching, not measured or calculated by a real program. The site labels them wherever they appear.', 'site', ['all'])
# ---------------------------------------------------------------- structure
G('pdb', 'PDB', ['PDB'], 'Protein Data Bank', 'The public archive of 3D structures of proteins and other molecules. Each entry has a four-character ID, for example 3LN1 (COX-2 with celecoxib).', 'structure', ['docking', 'homology', 'project'])
G('rcsb', 'RCSB', ['RCSB'], 'Research Collaboratory for Structural Bioinformatics', 'The organisation and website (rcsb.org) through which PDB entries are searched and downloaded.', 'structure', ['docking'])
