# ---------------------------------------------------------------- docking
G('docking', 'Docking', [], '', 'A computer experiment that predicts how a small molecule fits into a protein pocket (the pose) and estimates how well (the score).', 'docking', ['docking'])
G('pose', 'Pose', [], '', 'A predicted position and orientation (and shape) of a ligand in the pocket.', 'docking', ['docking'])
G('score', 'Docking score', [], 'Scoring function value (kcal/mol)', 'A rough estimate of binding strength. More negative is better. It is the least reliable part of docking, so use it with the pose and interactions.', 'docking', ['docking', 'screening'])
G('box', 'Search box (grid box)', [], '', 'The region of the protein in which the docking program looks for poses. It should cover the whole pocket with a margin, but not be far larger.', 'docking', ['docking', 'project'])
