G('redocking', 'Redocking', [], '', 'Docking the ligand that is already in a crystal structure back into it, to check that the protocol can reproduce the known pose. An RMSD of 2 Å or less is the usual aim.', 'docking', ['docking', 'project'])
G('rmsd', 'RMSD', ['RMSD'], 'Root-mean-square deviation', 'A measure of how far one set of atoms is from another, in Å. Used to compare a docked pose with the crystal pose, a model with the true structure, or a simulation frame with the start.', 'docking', ['docking', 'homology', 'md', 'project'], 'RMSD = √( Σ d² / N ), where d is the distance between matching atoms and N the number of atoms.')
G('le', 'Ligand efficiency', ['LE'], 'Ligand efficiency', 'Docking score divided by the number of heavy atoms (kcal/mol per atom). It stops large molecules looking better just because they are large.', 'docking', ['docking', 'project'], 'LE = −score / heavy atoms.')
G('hbond', 'Hydrogen bond (H-bond)', ['H-bond', 'H-bonds'], '', 'A strong electrical attraction between a hydrogen on one atom (donor) and a nitrogen or oxygen on another (acceptor), about 2.7 to 3.3 Å long. A key way drugs hold on to proteins.', 'docking', ['docking', 'md', 'project'])
G('hydrophobic', 'Hydrophobic contact', [], '', 'Oily parts of the ligand and protein packed together, away from water. Many small contacts add up.', 'docking', ['docking'])
G('keyres', 'Key residues', [], '', 'Pocket residues known to matter for binding (for COX-2: HIS90, GLN192, ARG513).', 'docking', ['docking', 'project'])
G('control', 'Reference compound (control)', [], '', 'A known active drug run through the same method, so that new compounds have something to be compared with.', 'docking', ['docking', 'screening', 'project'])
G('clash', 'Clash', [], 'Steric clash', 'Two atoms that are closer than is physically possible. A pose with clashes is not believable.', 'docking', ['docking', 'screening'])
# ---------------------------------------------------------------- screening
G('vs', 'Virtual screening', [], '', 'Using a computer to rank or filter a large library of compounds to find a few worth testing.', 'screening', ['screening'])
G('library', 'Compound library', [], '', 'A collection of compounds (real or virtual) that is screened.', 'screening', ['screening'])
G('lb', 'Ligand-based screening', [], '', 'Searching for compounds that resemble a known active, by 2D similarity or 3D shape.', 'screening', ['screening'])
G('sb', 'Structure-based screening', [], '', 'Searching by fitting compounds into the 3D structure of the target (docking).', 'screening', ['screening'])
G('tanimoto', 'Tanimoto coefficient', [], 'Tanimoto similarity', 'A number from 0 to 1 that says how similar two molecules are from their fingerprints (lists of structural features). 1 means identical.', 'screening', ['screening'], 'Tc = shared features / (features in A + features in B − shared features).')
G('fingerprint', 'Fingerprint', [], 'Molecular fingerprint', 'A string of 1s and 0s that records which structural features a molecule has. Used to compare molecules quickly.', 'screening', ['screening'])
G('shape', 'Shape overlay', [], '', 'Laying one molecule on another in 3D and measuring how much of their volumes overlap.', 'screening', ['screening'])
G('ro5', 'Rule of five', ['Ro5'], 'Lipinski\'s rule of five', 'A rule of thumb for oral drugs: molecular weight ≤ 500, cLogP ≤ 5, hydrogen-bond donors ≤ 5, acceptors ≤ 10. Breaking two or more makes poor absorption more likely.', 'screening', ['screening', 'adme', 'project'])
G('veber', 'Veber rules', [], '', 'A second rule of thumb for oral absorption: polar surface area ≤ 140 Å² and no more than 10 rotatable bonds.', 'adme', ['adme', 'project'])
G('pains', 'PAINS', ['PAINS'], 'Pan-assay interference compounds', 'Structures that often give false positives in lab tests, for example by reacting with the assay rather than binding the target. They are removed or treated with suspicion.', 'screening', ['screening', 'adme', 'project'])
G('funnel', 'Screening funnel', [], '', 'The series of filters that cut a large library down to a short list, with the number of compounds left after each.', 'screening', ['screening', 'project'])
G('ef', 'Enrichment factor', ['EF', 'EF10'], '', 'How many times more known actives are in the top part of a ranking than expected by chance. 1 means no better than random.', 'screening', ['screening', 'project'], 'EF = (actives in top n / n) / (actives overall / library size).')
G('roc', 'ROC curve', ['ROC'], 'Receiver operating characteristic curve', 'A graph of true positives against false positives as you move down a ranked list. A good method rises steeply.', 'screening', ['screening', 'project'])
G('auc', 'AUC', ['AUC'], 'Area under the curve', 'Two meanings in the site. In screening: area under the ROC curve, from 0.5 (random) to 1 (perfect). In ADME: area under the concentration–time curve, the total exposure to a drug.', 'screening', ['screening', 'adme', 'project'])
G('active', 'Active / decoy', [], '', 'A known active is a compound proven to hit the target. A decoy is assumed inactive. Mixing them tests whether a method can pick out the actives.', 'screening', ['screening', 'project'])
G('diversity', 'Diversity', [], '', 'How different the chosen compounds are from each other. Eight look-alikes test one idea eight times.', 'screening', ['screening'])
# ---------------------------------------------------------------- ADME
G('adme', 'ADME', ['ADME'], 'Absorption, distribution, metabolism, excretion', 'What the body does to a drug: how it gets into the blood (A), where it goes (D), how it is chemically changed (M) and how it is removed (E). Often written ADMET to add toxicity.', 'adme', ['adme', 'project'])
G('absorption', 'Absorption', [], '', 'Passage of a drug from where it is given (for example the gut) into the blood.', 'adme', ['adme'])
G('bioavail', 'Oral bioavailability', [], '', 'The fraction of an oral dose that reaches the blood unchanged.', 'adme', ['adme'])
G('gi', 'GI absorption', ['GI'], 'Gastrointestinal absorption', 'Predicted passage across the gut wall (high or low).', 'adme', ['adme', 'project'])
G('bbb', 'Blood–brain barrier', ['BBB'], 'Blood–brain barrier', 'A tight layer of cells that limits what can pass from blood into the brain. Some drugs need to cross it, some must not.', 'adme', ['adme'])
G('egg', 'BOILED-Egg', ['BOILED-Egg'], 'Brain Or IntestinaL EstimateD permeation', 'A plot of polar surface area against cLogP. Compounds in the white are predicted to be absorbed by the gut, and in the yolk to also enter the brain.', 'adme', ['adme'])
G('logp', 'logP / cLogP', ['cLogP', 'logP', 'LogP'], 'Partition coefficient (calculated)', 'How much a compound prefers oil to water, on a log scale. High values mean greasy. cLogP is the calculated value.', 'adme', ['adme', 'screening', 'project'])
G('tpsa', 'TPSA', ['TPSA'], 'Topological polar surface area', 'The surface area (Å²) of the polar atoms (N, O and their hydrogens). High values hinder crossing cell membranes.', 'adme', ['adme', 'screening', 'project'])
G('hbd', 'HBD / HBA', ['HBD', 'HBA'], 'Hydrogen-bond donors / acceptors', 'The number of groups that can give (HBD) or accept (HBA) a hydrogen bond.', 'adme', ['adme', 'screening', 'project'])
G('mw', 'MW', ['MW'], 'Molecular weight', 'The mass of a molecule in daltons (Da). Larger molecules are usually absorbed less well.', 'adme', ['adme', 'screening', 'project'])
G('rotb', 'Rotatable bonds', ['RotB'], '', 'Single bonds that can rotate freely. Many of them make a molecule floppy and harder to absorb.', 'adme', ['adme', 'screening', 'project'])
G('logs', 'logS / ESOL', ['logS', 'ESOL'], 'Solubility on a log scale (estimate)', 'logS is log10 of solubility in mol/L. ESOL is a simple equation (Delaney 2004) that estimates it from cLogP, weight, rotatable bonds and aromatic proportion.', 'adme', ['adme'])
G('pka', 'pKa', ['pKa'], '', 'The pH at which half of a group is ionised. Acids are mostly neutral below their pKa, bases above it.', 'adme', ['adme'])
G('ph', 'pH', ['pH'], '', 'A measure of acidity. The stomach is about pH 1.5 to 2, blood 7.4.', 'adme', ['adme', 'project'])
G('hh', 'Henderson–Hasselbalch', [], 'Henderson–Hasselbalch equation', 'Links pH and pKa to the fraction of a compound that is ionised. Only the neutral form crosses membranes easily.', 'adme', ['adme'], 'For an acid: fraction neutral = 1 / (1 + 10^(pH − pKa)). For a base: 1 / (1 + 10^(pKa − pH)).')
G('cyp', 'CYP', ['CYP', 'P450', 'CYP2C9', 'CYP1A2', 'CYP2D6', 'CYP2E1'], 'Cytochrome P450', 'A family of liver enzymes that chemically change most drugs (phase I metabolism). CYP2C9 handles celecoxib.', 'adme', ['adme', 'project'])
G('phase', 'Phase I / Phase II', [], 'Metabolic phases', 'Phase I reactions (oxidation, hydrolysis) expose or add a reactive group. Phase II reactions attach a polar group (for example glucuronic acid) so the kidney can remove it.', 'adme', ['adme'])
G('softspot', 'Soft spot', [], 'Metabolic soft spot', 'A part of a molecule that enzymes attack readily, for example an aromatic methyl group or an ester.', 'adme', ['adme'])
G('napqi', 'NAPQI', ['NAPQI'], 'N-acetyl-p-benzoquinone imine', 'The toxic metabolite of paracetamol. In overdose it damages the liver.', 'adme', ['adme'])
G('pampa', 'PAMPA', ['PAMPA'], 'Parallel artificial membrane permeability assay', 'A laboratory test of how well a compound passes through an artificial membrane by passive diffusion.', 'adme', ['adme'])
G('halflife', 'Half-life', [], 't½', 'The time for the blood level of a drug to fall by half.', 'adme', ['adme'])
G('cmax', 'Cmax / Tmax', ['Cmax', 'Tmax'], '', 'The highest concentration of a drug in the blood (Cmax) and the time at which it is reached (Tmax).', 'adme', ['adme'])
G('clearance', 'Clearance / volume of distribution', [], '', 'Clearance (CL) is the volume of blood cleared of drug per unit time. Volume of distribution (V) relates the amount in the body to the blood concentration.', 'adme', ['adme'])
