G('genesym', 'Gene symbol', ['PTGS2', 'PTGS1', 'TNF', 'AKT1', 'STAT3'], '', 'The short official name of a gene, for example PTGS2 (COX-2), TNF (tumour necrosis factor), AKT1 and STAT3 (signalling proteins).', 'network', ['network'])
G('ca', 'Carbonic anhydrase', ['CA2', 'CA9', 'CA12'], 'CA2, CA9, CA12', 'Enzymes that interconvert CO₂ and bicarbonate. Celecoxib is reported to inhibit some of them, which is why they appear as celecoxib targets outside the inflammation picture.', 'network', ['network'])
G('genecards', 'GeneCards / DisGeNET', ['GeneCards', 'DisGeNET'], '', 'Databases linking genes to diseases, each with a score (a relevance score in GeneCards, a gene–disease association score in DisGeNET). Used to collect disease genes.', 'network', ['network', 'project'])
G('stp', 'SwissTargetPrediction / PharmMapper', ['SwissTargetPrediction', 'PharmMapper'], '', 'Web tools that predict likely protein targets of a compound: the first from its similarity to known ligands (with a probability), the second by fitting it to 3D pharmacophores.', 'network', ['network', 'project'])
# ---------------------------------------------------------------- homology
G('hm', 'Homology modelling', [], 'Comparative modelling', 'Building a 3D model of a protein from its sequence, using the known structure of a related protein as a template.', 'homology', ['homology', 'project'])
G('template', 'Template', [], '', 'The known structure that a homology model is built from.', 'homology', ['homology'])
G('identity', 'Sequence identity', [], '', 'The share of positions where two aligned sequences have the same amino acid. Above about 40% the model is usually good, below 30% (the twilight zone) the alignment is unreliable.', 'homology', ['homology', 'project'])
G('alignment', 'Alignment', [], 'Sequence alignment', 'Lining up two sequences so that matching positions sit in the same column, with gaps where one has extra residues.', 'homology', ['homology'])
G('gap', 'Gap penalty', [], '', 'The cost of opening or extending a gap in an alignment. Gaps belong in loops, not inside helices or strands.', 'homology', ['homology'])
G('blosum', 'BLOSUM62', ['BLOSUM62'], '', 'A table that scores how likely one amino acid is to replace another during evolution. Used to score alignments.', 'homology', ['homology'])
G('ramachandran', 'Ramachandran plot', [], '', 'A plot of the backbone angles φ and ψ of each residue. Real proteins fill certain allowed regions. Good models have over 90% of residues in the favoured region.', 'homology', ['homology', 'project'])
G('ca_trace', 'C-alpha (Cα) trace', ['CA'], '', 'A backbone drawn through only the central carbon atom of each residue. A simplified model.', 'homology', ['homology'])
G('plddt', 'pLDDT', ['pLDDT'], 'Predicted local distance difference test', 'The per-residue confidence score (0 to 100) of an AlphaFold prediction. Above 90 is very high, below 70 is low.', 'homology', ['homology', 'project'])
G('alphafold', 'AlphaFold', ['AlphaFold'], '', 'A deep-learning program that predicts protein structures from sequence.', 'homology', ['homology', 'project'])
G('modeller', 'MODELLER / SWISS-MODEL', ['MODELLER', 'SWISS-MODEL'], '', 'Programs that build homology models, including side chains and refinement.', 'homology', ['homology'])
G('verify', 'Verify3D / ProSA', ['Verify3D', 'ProSA'], '', 'Programs that check whether the amino acids of a model sit in suitable environments (buried or exposed).', 'homology', ['homology'])
G('chothia', 'Chothia–Lesk curve', [], '', 'An observed relationship between sequence identity and expected structural difference between related proteins (1986). Higher identity means a smaller expected RMSD.', 'homology', ['homology'])
G('ampa', 'AMPA receptor / GluA2 / GluA3 / NTD', ['AMPA', 'GluA2', 'GluA3', 'NTD'], '', 'AMPA receptors carry fast excitatory signals in the brain. GluA2 and GluA3 are two of their subunits. NTD is the N-terminal domain. The homology module uses their real structures as the example.', 'homology', ['homology'])
# ---------------------------------------------------------------- MD
