G('verlet', 'Velocity Verlet', [], '', 'The standard method for moving atoms forward one time step from their forces.', 'md', ['md'])
G('lj', 'Lennard-Jones', [], 'Lennard-Jones potential', 'A simple force between two atoms: attraction at a distance and strong repulsion up close.', 'md', ['md'])
