G('production', 'Production run', [], '', 'The part of a simulation that is analysed.', 'md', ['md', 'project'])
G('minimise', 'Energy minimisation', [], '', 'Moving atoms to relieve clashes and huge forces before dynamics starts.', 'md', ['md', 'project'])
G('traj', 'Trajectory', [], '', 'The saved positions of all atoms at many time points.', 'md', ['md'])
G('replica', 'Replica', [], '', 'An independent repeat of a simulation from different starting velocities. One run is one sample.', 'md', ['md', 'project'])
G('rmsf', 'RMSF', ['RMSF'], 'Root-mean-square fluctuation', 'How much each residue moves around its average position during a simulation. Loops and chain ends usually move most.', 'md', ['md'])
G('rg', 'Radius of gyration', ['Rg'], '', 'A measure of how compact a protein is. A steady value means the protein keeps its overall shape.', 'md', ['md'])
G('occupancy', 'H-bond occupancy', [], '', 'The percentage of simulation frames in which a particular hydrogen bond is present.', 'md', ['md', 'project'])
G('mmgbsa', 'MM-GBSA / MM-PBSA', ['MM-GBSA', 'MM-PBSA'], 'Molecular mechanics with generalised Born (or Poisson–Boltzmann) and surface area', 'A quick end-point method that estimates binding free energy from simulation frames. It gives a rough ranking, not an accurate binding energy, and usually leaves out entropy.', 'md', ['md', 'project'])
G('dg', 'ΔG (binding free energy)', ['ΔG'], 'Gibbs free energy of binding', 'The energy change on binding, in kcal/mol. More negative means tighter binding.', 'md', ['md', 'docking'])
